import { useState, useMemo, useEffect, useRef } from 'react';
import { Search, Plus, MoreVertical, ArrowLeft, Save, Edit3, Trash2, Printer, FileText, CheckCircle2, Clock, ShoppingCart } from 'lucide-react';
import Select from 'react-select';
import Pagination from '../components/Pagination';
import usePagination from '../hooks/usePagination';
import { getProducts } from '../services/api';

export default function PurchaseRequisition() {
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingProducts, setLoadingProducts] = useState(false);

  // Daftar item Inventory untuk pemilih Part Number (bukan ketik manual).
  const [inventoryItems, setInventoryItems] = useState([]);

  // Muat item Inventory sekali saat halaman dibuka.
  useEffect(() => {
    let active = true;
    const loadProducts = async () => {
      setLoadingProducts(true);
      try {
        const res = await getProducts('');
        const rows = res.data?.data || res.data || [];
        if (active) setInventoryItems(Array.isArray(rows) ? rows : []);
      } catch (err) {
        console.error('Gagal memuat daftar barang inventory:', err);
        if (active) setInventoryItems([]);
      } finally {
        if (active) setLoadingProducts(false);
      }
    };
    loadProducts();
    return () => { active = false; };
  }, []);

  // Opsi react-select: value dipakai sebagai id produk, label = kode — nama.
  const productOptions = useMemo(() => inventoryItems.map((inv) => {
    const code = inv.part_number || inv.product_code || inv.barcode;
    const name = inv.name || inv.description || '';
    return {
      value: inv.id,
      code,
      name,
      unit: inv.unit || 'PCS',
      label: name ? `${code} — ${name}` : code,
      raw: inv,
    };
  }), [inventoryItems]);

  const [viewMode, setViewMode] = useState('list'); // 'list' atau 'form'
  const [activeMenuId, setActiveMenuId] = useState(null);
  const [editingId, setEditingId] = useState(null);

  // Counter untuk menghasilkan id baris item yang unik & stabil.
  const rowSeq = useRef(0);

  // Data Dummy Permintaan Pembelian (PR)
  const [dummyPRs, setDummyPRs] = useState([
    {
      id: 1,
      prNo: 'PR-20260928-7683',
      date: '2026-09-28',
      department: 'Produksi',
      requester: 'Farel',
      remarks: 'Kebutuhan material perakitan bulanan',
      status: 'Menunggu',
      items: [
        { id: 101, partNumber: 'PART-001 - Pipa Besi 2 Inch', quantity: 20, unit: 'Batang' },
        { id: 102, partNumber: 'PART-005 - Baut Baja M10', quantity: 100, unit: 'Pcs' }
      ]
    },
    {
      id: 2,
      prNo: 'PR-20260927-1102',
      date: '2026-09-27',
      department: 'Maintenance',
      requester: 'Budi',
      remarks: 'Penggantian sparepart mesin harian',
      status: 'Disetujui',
      items: [
        { id: 201, partNumber: 'PART-012 - Bearing 6204', quantity: 4, unit: 'Pcs' }
      ]
    }
  ]);

  const filteredPRs = useMemo(() => {
    return dummyPRs.filter(item =>
      item.prNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.department.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [dummyPRs, searchTerm]);

  const pagination = usePagination(filteredPRs, 10);

  // State Form Input
  const [formData, setFormData] = useState({
    prNo: 'PR-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.floor(1000 + Math.random() * 9000),
    date: new Date().toISOString().split('T')[0],
    department: 'Produksi',
    requester: 'Administrator',
    remarks: '',
    status: 'Menunggu',
    items: [{ id: Date.now(), productId: null, partNumber: '', quantity: 1, unit: 'PCS' }]
  });

  const handleOpenAddForm = () => {
    setEditingId(null);
    setFormData({
      prNo: 'PR-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.floor(1000 + Math.random() * 9000),
      date: new Date().toISOString().split('T')[0],
      department: 'Produksi',
      requester: 'Administrator',
      remarks: '',
      status: 'Menunggu',
      items: [{ id: Date.now(), productId: null, partNumber: '', quantity: 1, unit: 'PCS' }]
    });
    setViewMode('form');
  };

  const handleOpenEditForm = (item) => {
    setEditingId(item.id);
    setFormData({ ...item });
    setViewMode('form');
    setActiveMenuId(null);
  };

  /* Penanda unik per baris item. `Date.now()` bisa sama untuk dua baris yang
   * dibuat dalam milidetik yang sama — itu membuat update/perubahan baris
   * tidak konsisten. Gunakan counter yang selalu bertambah. */
  const nextRowId = () => (Date.now() + (rowSeq.current++));

  const handleAddItemRow = () => {
    setFormData(prevForm => ({
      ...prevForm,
      items: [...prevForm.items, { id: nextRowId(), productId: null, partNumber: '', quantity: 1, unit: 'PCS' }]
    }));
  };

  const handleRemoveItemRow = (id) => {
    if (formData.items.length === 1) {
      alert('Permintaan minimal harus memiliki 1 item barang!');
      return;
    }
    setFormData(prevForm => ({
      ...prevForm,
      items: prevForm.items.filter(i => i.id !== id)
    }));
  };

  const handleItemChange = (id, field, value) => {
    setFormData(prevForm => ({
      ...prevForm,
      items: prevForm.items.map(i => i.id === id ? { ...i, [field]: value } : i)
    }));
  };

  // Saat pengguna memilih barang dari inventory: simpan product_id, part number,
  // nama barang, dan default satuan agar bisa dikirim ke backend sebagai product_id.
  const handleProductSelect = (id, option) => {
    setFormData({
      ...formData,
      items: formData.items.map(i => i.id === id ? {
        ...i,
        productId: option ? option.value : null,
        partNumber: option ? option.label : '',
        unit: option ? (option.unit || option.raw?.unit || i.unit) : i.unit,
      } : i)
    });
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!formData.department.trim()) {
      alert('Departemen wajib diisi!');
      return;
    }

    // Setiap baris wajib memilih barang dari inventory (bukan ketik bebas).
    const belumDipilih = formData.items.find(i => !i.productId);
    if (belumDipilih) {
      alert('Setiap item harus dipilih dari daftar inventory. Ketik Part Number atau Nama Barang pada kolom pencarian.');
      return;
    }

    if (editingId) {
      setDummyPRs(dummyPRs.map(item => item.id === editingId ? { ...item, ...formData } : item));
    } else {
      setDummyPRs([{ id: Date.now(), ...formData }, ...dummyPRs]);
    }
    setViewMode('list');
  };

  const handleDelete = (id) => {
    if (window.confirm('Apakah Anda yakin ingin menghapus Permintaan Pembelian ini?')) {
      setDummyPRs(dummyPRs.filter(item => item.id !== id));
      setActiveMenuId(null);
    }
  };

  // --- FUNGSI KONVERSI PR KE PURCHASE ORDER (PO) ---
  const handleConvertToPO = (prItem) => {
    setActiveMenuId(null);

    // Format item PR agar cocok dengan struktur Purchase Order.
    // partNumber disimpan sebagai "kode — nama"; pisahkan agar backend PO/DO
    // tetap bisa menemukan produk berdasarkan part number/kode.
    const poItems = prItem.items.map(i => {
      const [code, ...rest] = String(i.partNumber || '').split(' — ');
      return {
        part_number: code.trim(),
        description: rest.join(' — ').trim() || i.partNumber,
        qty: i.quantity,
        unit: i.unit || 'PCS',
        unit_price: 0 // Default harga satuan bisa diisi nanti di form PO
      };
    });

    const newPO = {
      id: Date.now(),
      po_number: 'PO-' + prItem.prNo.replace('PR-', ''),
      date: new Date().toISOString().split('T')[0],
      supplier_name: 'Supplier Umum (' + prItem.department + ')',
      supplier_address: 'Jakarta',
      subject: prItem.remarks || 'Pengadaan dari ' + prItem.prNo,
      items: poItems,
      status: 'Pending'
    };

    // Simpan ke local storage agar terbaca di halaman POList
    const existingPOs = JSON.parse(localStorage.getItem('aldigens_purchase_orders') || '[]');
    localStorage.setItem('aldigens_purchase_orders', JSON.stringify([newPO, ...existingPOs]));

    alert(`PR ${prItem.prNo} berhasil diproses menjadi Purchase Order (PO)! Silakan buka menu Purchase Order.`);
  };

  const handlePrint = (item) => {
    setActiveMenuId(null);
    const printWindow = window.open('', '_blank');
    printWindow.document.write(`
      <html><head><title>PR - ${item.prNo}</title><style>body{font-family:Arial;padding:20px} table{width:100%;border-collapse:collapse;margin-top:15px} th,td{padding:8px;border:1px solid #ddd;text-align:left}</style></head>
      <body>
        <h2>PT. ALDIGENS PUTERA PERSADA</h2>
        <h3>FORM PERMINTAAN PEMBELIAN (PURCHASE REQUISITION)</h3>
        <p><strong>No. PR:</strong> ${item.prNo}</p>
        <p><strong>Tanggal:</strong> ${item.date} | <strong>Departemen:</strong> ${item.department} | <strong>Pemohon:</strong> ${item.requester}</p>
        <p><strong>Keterangan:</strong> ${item.remarks || '-'}</p>
        <h4>Daftar Item Diminta:</h4>
        <table>
          <thead><tr><th>No</th><th>Part Number / Nama Barang</th><th>Kuantitas</th><th>Satuan</th></tr></thead>
          <tbody>
            ${item.items.map((i, idx) => `<tr><td>${idx + 1}</td><td>${i.partNumber}</td><td>${i.quantity}</td><td>${i.unit}</td></tr>`).join('')}
          </tbody>
        </table>
      </body></html>
    `);
    printWindow.document.close(); printWindow.print();
  };

  // --- TAMPILAN FORM ---
  if (viewMode === 'form') {
    return (
      <div className="p-6 max-w-5xl mx-auto">
        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-800 p-8">

          <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-200 dark:border-slate-800">
            <div className="flex items-center gap-3">
              <button onClick={() => setViewMode('list')} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">
                <ArrowLeft className="h-5 w-5 text-slate-500" />
              </button>
              <div>
                <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100">
                  {editingId ? 'Edit Permintaan Pembelian (PR)' : 'Buat Permintaan Pembelian Baru'}
                </h2>
                <p className="text-xs text-slate-500">Formulir pengajuan kebutuhan barang dan material perusahaan</p>
              </div>
            </div>
            <span className="px-3 py-1 bg-blue-50 dark:bg-blue-950/50 text-blue-600 dark:text-blue-400 rounded-full text-xs font-semibold">
              {formData.prNo}
            </span>
          </div>

          <form onSubmit={handleSave} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50 dark:bg-slate-950/50 p-5 rounded-xl border border-slate-200/60 dark:border-slate-800">
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">No. PR</label>
                <input type="text" value={formData.prNo} disabled className="w-full px-4 py-2.5 bg-slate-200/60 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-xl text-sm font-medium text-slate-600 dark:text-slate-400 cursor-not-allowed" />
              </div>
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Tanggal Permintaan</label>
                <input required type="date" value={formData.date} onChange={(e) => setFormData({ ...formData, date: e.target.value })} className="w-full px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 dark:text-white" />
              </div>
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Departemen</label>
                <input required type="text" placeholder="Contoh: Produksi / Maintenance" value={formData.department} onChange={(e) => setFormData({ ...formData, department: e.target.value })} className="w-full px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 dark:text-white" />
              </div>
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Pemohon (Requester)</label>
                <input required type="text" placeholder="Nama pemohon..." value={formData.requester} onChange={(e) => setFormData({ ...formData, requester: e.target.value })} className="w-full px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 dark:text-white" />
              </div>
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Status</label>
                <select value={formData.status} onChange={(e) => setFormData({ ...formData, status: e.target.value })} className="w-full px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 dark:text-white">
                  <option value="Menunggu">Menunggu (Pending)</option>
                  <option value="Disetujui">Disetujui (Approved)</option>
                </select>
              </div>
              <div className="md:col-span-3">
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Keterangan / Catatan</label>
                <textarea rows="2" placeholder="Catatan atau alasan permintaan..." value={formData.remarks} onChange={(e) => setFormData({ ...formData, remarks: e.target.value })} className="w-full px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 dark:text-white"></textarea>
              </div>
            </div>

            {/* Tabel Item Dinamis */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300 flex items-center gap-2">
                  <FileText className="h-4 w-4 text-blue-500" /> Daftar Item yang Diminta
                </h3>
                <button type="button" onClick={handleAddItemRow} className="flex items-center gap-1.5 text-xs bg-blue-50 hover:bg-blue-100 dark:bg-blue-950/50 dark:hover:bg-blue-900/50 text-blue-600 dark:text-blue-400 font-semibold px-3 py-1.5 rounded-lg transition">
                  <Plus className="h-3.5 w-3.5" /> Tambah Baris Item
                </button>
              </div>

              <div className="border border-slate-200 dark:border-slate-800 rounded-xl">
                <table className="w-full text-left text-sm">
                  <thead className="bg-slate-100 dark:bg-slate-950 text-slate-500 text-xs uppercase font-semibold">
                    <tr>
                      <th className="px-4 py-3 w-12 text-center">#</th>
                      <th className="px-4 py-3">Part Number / Nama Barang</th>
                      <th className="px-4 py-3 w-36">Kuantitas</th>
                      <th className="px-4 py-3 w-32">Satuan</th>
                      <th className="px-4 py-3 w-16 text-center">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200 dark:divide-slate-800 bg-white dark:bg-slate-900">
                    {formData.items.map((item, index) => (
                      <tr key={item.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/30">
                        <td className="px-4 py-3 text-center text-slate-400 font-medium text-xs">{index + 1}</td>
<<<<<<< HEAD
                        <td className="px-4 py-3">
                          <Select
                            inputId={`pr-item-product-${item.id}`}
                            classNamePrefix="pr-select"
                            className="react-select-container"
                            placeholder="Ketik Part Number / Nama Barang..."
                            isClearable
                            isSearchable
                            isLoading={loadingProducts}
                            options={productOptions}
                            value={productOptions.find(o => o.value === item.productId) || null}
                            onChange={(option) => handleProductSelect(item.id, option)}
                            noOptionsMessage={() => 'Barang tidak ditemukan di inventory'}
                            loadingMessage={() => 'Memuat daftar barang...'}
                            menuPortalTarget={typeof document !== 'undefined' ? document.body : undefined}
                            styles={{ menuPortal: (base) => ({ ...base, zIndex: 9999 }) }}
                          />
                        </td>
                        <td className="px-4 py-3">
                          <input required type="number" min="1" value={item.quantity} onChange={(e) => handleItemChange(item.id, 'quantity', Number(e.target.value))} className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 dark:text-white" />
                        </td>
                        <td className="px-4 py-3">
                          <select value={item.unit} onChange={(e) => handleItemChange(item.id, 'unit', e.target.value)} className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 dark:text-white">
                            <option value="PCS">PCS</option>
                            <option value="Unit">Unit</option>
                            <option value="Batang">Batang</option>
                            <option value="Kg">Kg</option>
                            <option value="Set">Set</option>
                            <option value="Meter">Meter</option>
                          </select>
                        </td>
                        <td className="px-4 py-3 text-center">
                          <button type="button" onClick={() => handleRemoveItemRow(item.id)} className="p-1.5 hover:bg-rose-50 dark:hover:bg-rose-950/30 text-rose-500 rounded-lg transition" title="Hapus Baris">
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </td>
                      </tr >
                    ))
  }
                  </tbody >
                </table >
              </div >
            </div >

    <div className="flex justify-end gap-3 pt-6 border-t border-slate-200 dark:border-slate-800">
      <button type="button" onClick={() => setViewMode('list')} className="px-6 py-2.5 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl font-medium transition">Batal</button>
      <button type="submit" className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl font-medium shadow-lg shadow-blue-500/25 transition">
        <Save className="h-4 w-4" /> Simpan Permintaan (PR)
      </button>
    </div>
          </form >
        </div >
      </div >
    );
}

// --- TAMPILAN DAFTAR (LIST) ---
return (
  <div className="p-6">
    <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800">

      <div className="p-5 border-b border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <input
              type="text"
              placeholder="Cari no. PR atau departemen..."
              className="pl-10 pr-4 py-2.5 w-full sm:w-80 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:text-slate-200"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <button onClick={handleOpenAddForm} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-sm font-semibold shadow-lg shadow-blue-500/25 transition cursor-pointer">
          <Plus className="h-4 w-4" />
          Simpan PR
        </button>
      </div>

      <div className="overflow-x-auto min-h-[350px]">
        <table className="w-full text-left text-sm whitespace-nowrap">
          <thead className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 text-xs uppercase font-semibold">
            <tr>
              <th className="px-6 py-3.5">Tanggal</th>
              <th className="px-6 py-3.5">No. PR</th>
              <th className="px-6 py-3.5">Departemen</th>
              <th className="px-6 py-3.5">Pemohon</th>
              <th className="px-6 py-3.5">Keterangan</th>
              <th className="px-6 py-3.5">Status</th>
              <th className="px-6 py-3.5 text-center">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-800 text-slate-700 dark:text-slate-300">
            {pagination.paginatedItems.length === 0 ? (
              <tr>
                <td colSpan="7" className="px-6 py-12 text-center text-slate-400">
                  Tidak ada data Permintaan Pembelian (PR) ditemukan.
                </td>
              </tr>
            ) : pagination.paginatedItems.map((item) => (
              <tr key={item.id} className="hover:bg-slate-50/60 dark:hover:bg-slate-800/40 transition relative">
                <td className="px-6 py-4">{item.date}</td>
                <td className="px-6 py-4 font-bold text-blue-600 dark:text-blue-400">{item.prNo}</td>
                <td className="px-6 py-4 font-semibold text-slate-800 dark:text-slate-100">{item.department}</td>
                <td className="px-6 py-4">{item.requester}</td>
                <td className="px-6 py-4 text-slate-500">{item.remarks || '-'}</td>
                <td className="px-6 py-4">
                  <span className={`px-2.5 py-1 rounded-full text-xs font-semibold flex items-center gap-1.5 w-max ${item.status === 'Disetujui' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-400' : 'bg-amber-100 text-amber-700 dark:bg-amber-950/50 dark:text-amber-400'}`}>
                    {item.status === 'Disetujui' ? <CheckCircle2 className="h-3.5 w-3.5" /> : <Clock className="h-3.5 w-3.5" />}
                    {item.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-center relative">
                  <button
                    onClick={() => setActiveMenuId(activeMenuId === item.id ? null : item.id)}
                    className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition cursor-pointer"
                  >
                    <MoreVertical className="h-4 w-4 inline" />
                  </button>

                  {activeMenuId === item.id && (
                    <div className="absolute right-12 top-10 w-44 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl py-1.5 z-20 text-left">
                      {item.status === 'Disetujui' && (
                        <button
                          onClick={() => handleConvertToPO(item)}
                          className="w-full px-4 py-2 text-xs font-medium flex items-center gap-2.5 hover:bg-indigo-50 dark:hover:bg-indigo-950/50 text-indigo-600 dark:text-indigo-400 border-b border-slate-100 dark:border-slate-700"
                        >
                          <ShoppingCart className="h-4 w-4" /> Proses ke PO
                        </button>
                      )}
                      <button
                        onClick={() => handleOpenEditForm(item)}
                        className="w-full px-4 py-2 text-xs font-medium flex items-center gap-2.5 hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200"
                      >
                        <Edit3 className="h-4 w-4 text-blue-500" /> Edit PR
                      </button>
                      <button
                        onClick={() => handlePrint(item)}
                        className="w-full px-4 py-2 text-xs font-medium flex items-center gap-2.5 hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200"
                      >
                        <Printer className="h-4 w-4 text-emerald-500" /> Cetak Dokumen
                      </button>
                      <button
                        onClick={() => handleDelete(item.id)}
                        className="w-full px-4 py-2 text-xs font-medium flex items-center gap-2.5 hover:bg-rose-50 dark:hover:bg-rose-950/30 text-rose-600 dark:text-rose-400 border-t border-slate-100 dark:border-slate-700"
                      >
                        <Trash2 className="h-4 w-4" /> Hapus PR
                      </button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination Controller */}
      <Pagination
        currentPage={pagination.currentPage}
        totalItems={pagination.totalItems}
        pageSize={pagination.pageSize}
        onPageChange={pagination.setCurrentPage}
        onPageSizeChange={pagination.setPageSize}
      />
    </div>
  </div>
);
}

import { useState, useEffect, useMemo } from 'react';
import { Search, Plus, ArrowLeft, Save, Trash2, Printer, MoreVertical, Edit2 } from 'lucide-react';
import Select from 'react-select';
import Pagination from '../components/Pagination';
import usePagination from '../hooks/usePagination';
import api, { getProducts } from '../services/api';

export default function ReceiveItem() {
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState('list'); // 'list' atau 'form'
  const [activeMenuId, setActiveMenuId] = useState(null);
  const [editingId, setEditingId] = useState(null);
  const [receiveItems, setReceiveItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState([]);

  // Daftar item Inventory untuk pemilih Part Number (bukan ketik manual).
  const [inventoryItems, setInventoryItems] = useState([]);

  // Form State, sekarang dengan tambahan deliveryOrder, spkSupplier, dan items
  const [formData, setFormData] = useState({
    receiveNo: 'RI-' + Math.floor(100000 + Math.random() * 900000),
    date: new Date().toISOString().split('T')[0],
    vendorName: '',
    poRef: '',
    deliveryOrder: '',
    spkSupplier: '',
    status: 'Completed',
    notes: '',
    items: [{ part_number: '', description: '', qty: 1, unit: 'PCS' }],
    items: [{ id: Date.now(), productId: null, quantity: 1 }],
  });

  // Opsi pencarian barang dari inventory (Part Number / Nama Barang).
  const productOptions = useMemo(() => products.map((p) => ({
    value: p.id,
    label: [p.part_number, p.name].filter(Boolean).join(' - ') || p.name || `#${p.id}`,
    raw: p,
  })), [products]);

  // Ambil data dari API Laravel atau LocalStorage saat halaman dibuka
  useEffect(() => {
    const fetchReceiveItems = async () => {
      try {
        setLoading(true);
        const response = await api.get('/receive-items').catch(() => null);
        const apiData = response?.data?.data || response?.data;

        if (Array.isArray(apiData) && apiData.length > 0) {
          setReceiveItems(apiData);
        } else {
          // Fallback: Ambil data dari local storage (hasil konversi dari PO)
          const localData = JSON.parse(localStorage.getItem('aldigens_receive_items') || '[]');
          setReceiveItems(localData);
        }
      } catch (error) {
        console.error('API Error, memuat data lokal...', error);
        // Fallback: Jika API error, langsung ambil dari local storage
        const localData = JSON.parse(localStorage.getItem('aldigens_receive_items') || '[]');
        setReceiveItems(localData);
      } finally {
        setLoading(false);
      }
    };

    const fetchProducts = async () => {
      try {
        const res = await getProducts();
        setProducts(res.data?.data ?? []);
      } catch (error) {
        console.error('Gagal memuat daftar barang inventory:', error);
      }
    };

    fetchReceiveItems();
    fetchInventoryItems();
    fetchProducts();
  }, []);

  /** Muat daftar produk Inventory untuk dropdown Part Number. */
  const fetchInventoryItems = async () => {
    try {
      let rows = [];
      try {
        const res = await getProducts('');
        rows = res.data?.data || res.data || [];
      } catch {
        rows = JSON.parse(localStorage.getItem('aldigens_products') || '[]');
      }
      setInventoryItems(Array.isArray(rows) ? rows : []);
    } catch {
      setInventoryItems([]);
    }
  };

  // Opsi react-select: value = part_number/kode, label = kode — nama.
  const productOptions = useMemo(() => inventoryItems.map((inv) => {
    const code = inv.part_number || inv.product_code || inv.barcode;
    return {
      value: code,
      label: `${code} — ${inv.name || inv.description || ''}`,
      name: inv.name || inv.description || '',
      unit: inv.unit || 'PCS',
    };
  }), [inventoryItems]);

  const handleAddItem = () => {
    setFormData((prev) => ({
      ...prev,
      items: [...prev.items, { part_number: '', description: '', qty: 1, unit: 'PCS' }],
    }));
  };

  const handleRemoveItem = (index) => {
    setFormData((prev) => ({
      ...prev,
      items: prev.items.length === 1 ? prev.items : prev.items.filter((_, i) => i !== index),
    }));
  };

  const handleItemChange = (index, field, value) => {
    setFormData((prev) => {
      const items = [...prev.items];
      items[index] = { ...items[index], [field]: value };
      return { ...prev, items };
    });
  };

  const fetchReceiveItems = async () => {
    try {
      setLoading(true);
      const response = await api.get('/receive-items').catch(() => null);
      const apiData = response?.data?.data || response?.data;

      if (Array.isArray(apiData) && apiData.length > 0) {
        setReceiveItems(apiData);
      } else {
        // Fallback: Ambil data dari local storage
        const localData = JSON.parse(localStorage.getItem('aldigens_receive_items') || '[]');
        setReceiveItems(localData);
      }
    } catch (error) {
      console.error('API Error, memuat data lokal...', error);
      // Fallback: Jika API error, langsung ambil dari local storage
      const localData = JSON.parse(localStorage.getItem('aldigens_receive_items') || '[]');
      setReceiveItems(localData);
    } finally {
      setLoading(false);
    }
  };

  const filteredReceiveItems = useMemo(() => {
    return receiveItems.filter(item => {
      const receiveNo = item.receive_no || item.ri_number || item.document_number || '';
      const vendor = item.vendor_name || item.supplier_name || '';

      return receiveNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
             vendor.toLowerCase().includes(searchTerm.toLowerCase());
    });
  }, [receiveItems, searchTerm]);

  const pagination = usePagination(filteredReceiveItems, 10);

  const handleInputChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleOpenAddForm = () => {
    setEditingId(null);
    setFormData({
      receiveNo: 'RI-' + Math.floor(100000 + Math.random() * 900000),
      date: new Date().toISOString().split('T')[0],
      vendorName: '',
      poRef: '',
      deliveryOrder: '',
      spkSupplier: '',
      status: 'Completed',
      notes: '',
      items: [{ part_number: '', description: '', qty: 1, unit: 'PCS' }],
      items: [{ id: Date.now(), productId: null, quantity: 1 }],
    });
    setViewMode('form');
  };

  const handleAddItemRow = () => {
    setFormData({
      ...formData,
      items: [...formData.items, { id: Date.now(), productId: null, quantity: 1 }],
    });
  };

  const handleRemoveItemRow = (id) => {
    if (formData.items.length === 1) {
      alert('Penerimaan minimal harus memiliki 1 item barang!');
      return;
    }
    setFormData({ ...formData, items: formData.items.filter((i) => i.id !== id) });
  };

  const handleItemChange = (id, field, value) => {
    setFormData({
      ...formData,
      items: formData.items.map((i) => (i.id === id ? { ...i, [field]: value } : i)),
    });
  };

  const handleProductSelect = (id, option) => {
    setFormData({
      ...formData,
      items: formData.items.map((i) => (i.id === id ? {
        ...i,
        productId: option ? option.value : null,
        partNumber: option ? option.label : '',
      } : i)),
    });
  };

  // Simpan data ke Database via API Laravel (dengan fallback ke localStorage)
  const handleSave = async (e) => {
    e.preventDefault();

    if (formData.items.some((i) => !i.productId)) {
      alert('Setiap item harus dipilih dari daftar inventory. Ketik Part Number atau Nama Barang pada kolom pencarian.');
      return;
    }

    const newRI = {
      receiveNo: formData.receiveNo,
      date: formData.date,
      vendorName: formData.vendorName,
      poRef: formData.poRef,

  // Buka Form untuk Edit Data
  const handleEdit = (item) => {
    setActiveMenuId(null);
    setEditingId(item.id);
    setFormData({
      receiveNo: item.receive_no || item.ri_number || item.document_number || '',
      date: item.date || item.receive_date || '',
      vendorName: item.vendor_name || item.supplier_name || '',
      poRef: item.po_ref || item.po_reference || '',
      deliveryOrder: item.delivery_order || '',
      spkSupplier: item.spk_supplier || '',
      status: item.status || 'Completed',
      notes: item.notes || '',
      items: (item.items || []).map((it) => ({
        part_number: it.part_number || it.product?.part_number || '',
        description: it.product?.name || it.description || '',
        qty: it.quantity || it.qty || 1,
        unit: it.unit || 'PCS',
      })),
    });
    if (!item.items || item.items.length === 0) {
      setFormData((prev) => ({ ...prev, items: [{ part_number: '', description: '', qty: 1, unit: 'PCS' }] }));
    }
    setViewMode('form');
  };

  // Simpan data ke Database (Create & Update)
  const handleSave = async (e) => {
    e.preventDefault();

    // Hanya baris item yang valid (punya part number) yang dikirim ke backend,
    // agar backend menambah stok Inventory untuk item tersebut.
    const validItems = formData.items
      .filter((it) => it.part_number)
      .map((it) => ({
        part_number: it.part_number,
        description: it.description,
        qty: Number(it.qty) || 1,
        unit: it.unit || 'PCS',
      }));

    // Sesuaikan properti untuk disimpan ke localStorage jika API error
    const newRI = {
      id: editingId || Date.now(),
      receive_no: formData.receiveNo,
      ri_number: formData.receiveNo,
      date: formData.date,
      vendor_name: formData.vendorName,
      supplier_name: formData.vendorName,
      po_ref: formData.poRef,
      delivery_order: formData.deliveryOrder,
      spk_supplier: formData.spkSupplier,
      status: formData.status,
      notes: formData.notes,
      items: validItems,
      items: formData.items.map((i) => ({
        product_id: i.productId,
        quantity: Number(i.quantity),
      })),
    };

    try {
      if (editingId) {
        // Proses Update (Edit)
        await api.put(`/receive-items/${editingId}`, { ...formData, items: validItems });
        alert('Data Penerimaan Barang berhasil diperbarui!');
      } else {
        // Proses Tambah Baru — backend akan menambah stok Inventory dari items.
        await api.post('/receive-items', { ...formData, items: validItems });
        alert('Data Penerimaan Barang berhasil disimpan dan stok Inventory bertambah!');
        await api.post('/receive-items', newRI);
        alert('Data Penerimaan Barang berhasil disimpan dan stok inventory otomatis bertambah!');
      }
    } catch (error) {
      console.error('Gagal menyimpan penerimaan barang:', error);
      alert(error?.response?.data?.message || 'Gagal menyimpan data penerimaan barang.');
      return;

        // Proses Tambah Baru
        await axios.post('http://127.0.0.1:8000/api/receive-items', formData);
        alert('Data Penerimaan Barang berhasil disimpan!');
      }
    } catch {
      console.log('API Error, menyimpan ke local storage...');
      const existingRIs = JSON.parse(localStorage.getItem('aldigens_receive_items') || '[]');
      if (editingId) {
        const updated = existingRIs.map(i => i.id === editingId ? newRI : i);
        localStorage.setItem('aldigens_receive_items', JSON.stringify(updated));
      } else {
        localStorage.setItem('aldigens_receive_items', JSON.stringify([newRI, ...existingRIs]));
      }
      alert('Disimpan ke penyimpanan lokal (Offline Mode). Pastikan backend Laravel menyala.');
    }

    fetchReceiveItems();
    setViewMode('list');
  };

  const handleDelete = async (id) => {
    if (window.confirm('Apakah Anda yakin ingin menghapus data penerimaan barang ini?')) {
      try {
        await api.delete(`/receive-items/${id}`);
      } catch {
        console.log('Menghapus data dari penyimpanan lokal...');
      } catch (error) {
        console.log('Gagal menghapus data penerimaan.', error);
      }
      
      const existingRIs = JSON.parse(localStorage.getItem('aldigens_receive_items') || '[]');
      const updatedRIs = existingRIs.filter(item => item.id !== id && item.receive_no !== id && item.ri_number !== id);
      localStorage.setItem('aldigens_receive_items', JSON.stringify(updatedRIs));
      
      fetchReceiveItems();
      setActiveMenuId(null);
    }
  };

  const handlePrint = (item) => {
    setActiveMenuId(null);
    const receiveNo = item.receive_no || item.ri_number || item.document_number || '-';
    const vendor = item.vendor_name || item.supplier_name || '-';
    const poRef = item.po_ref || item.po_reference || '-';

    const printWindow = window.open('', '_blank');
    printWindow.document.write(`
      <html><head><title>Penerimaan Barang - ${receiveNo}</title><style>body{font-family:sans-serif;padding:20px} table{width:100%;border-collapse:collapse;margin-top:15px} td{padding:8px;border:1px solid #ddd}</style></head>
      <body><h2>PT. ALDIGENS PUTERA PERSADA</h2><h3>BUKTI PENERIMAAN BARANG (RECEIVE ITEM)</h3>
      <table>
        <tr><td><strong>No. Penerimaan</strong></td><td>${receiveNo}</td></tr>
        <tr><td><strong>Tanggal</strong></td><td>${item.date || item.receive_date}</td></tr>
        <tr><td><strong>Vendor</strong></td><td>${vendor}</td></tr>
        <tr><td><strong>Ref. PO</strong></td><td>${poRef}</td></tr>
        <tr><td><strong>Delivery Order (DO)</strong></td><td>${item.delivery_order || '-'}</td></tr>
        <tr><td><strong>No. SPK</strong></td><td>${item.spk_supplier || '-'}</td></tr>
        <tr><td><strong>Status</strong></td><td>${item.status}</td></tr>
        <tr><td><strong>Catatan</strong></td><td>${item.notes || '-'}</td></tr>
      </table></body></html>
    `);
    printWindow.document.close(); printWindow.print();
  };

  if (viewMode === 'form') {
    return (
      <div className="p-6">
        <div className="bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 p-6">
          <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-200 dark:border-slate-800">
            <button onClick={() => setViewMode('list')} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg"><ArrowLeft className="h-5 w-5 text-slate-500" /></button>
            <h2 className="text-xl font-semibold dark:text-white">
              {editingId ? 'Edit Terima Barang' : 'Form Terima Barang Baru'}
            </h2>
          </div>
          <form onSubmit={handleSave} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              
              <div><label className="block text-sm font-medium dark:text-slate-300 mb-1">No. Penerimaan (RI)</label><input required type="text" name="receiveNo" value={formData.receiveNo} onChange={handleInputChange} disabled={!!editingId} className={`w-full px-4 py-2 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500 ${editingId ? 'bg-slate-100 dark:bg-slate-800 cursor-not-allowed' : 'bg-slate-50 dark:bg-slate-950'}`} /></div>
              
              <div><label className="block text-sm font-medium dark:text-slate-300 mb-1">Tanggal</label><input required type="date" name="date" value={formData.date} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500" /></div>
              
              <div><label className="block text-sm font-medium dark:text-slate-300 mb-1">Vendor</label><input required type="text" name="vendorName" value={formData.vendorName} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500" placeholder="Nama Pemasok..." /></div>
              
              <div><label className="block text-sm font-medium dark:text-slate-300 mb-1">Ref. PO</label><input type="text" name="poRef" value={formData.poRef} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500" placeholder="Nomor PO..." /></div>

              {/* INPUT BARU UNTUK DO DAN SPK */}
              <div><label className="block text-sm font-medium dark:text-slate-300 mb-1">Delivery Order (DO) Supplier</label><input type="text" name="deliveryOrder" value={formData.deliveryOrder} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500" placeholder="Nomor DO / Surat Jalan..." /></div>

              <div><label className="block text-sm font-medium dark:text-slate-300 mb-1">Ref. SPK Supplier</label><input type="text" name="spkSupplier" value={formData.spkSupplier} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500" placeholder="Nomor SPK dari Pemasok..." /></div>

              <div>
                <label className="block text-sm font-medium dark:text-slate-300 mb-1">Status</label>
                <select name="status" value={formData.status} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500">
                  <option value="Completed">Selesai Diterima (Completed)</option>
                  <option value="Partial">Diterima Sebagian (Partial)</option>
                </select>
              </div>
              
              <div className="md:col-span-2">
                <label className="block text-sm font-medium dark:text-slate-300 mb-1">Catatan</label>
                <textarea name="notes" value={formData.notes} onChange={handleInputChange} rows="3" className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg dark:text-white outline-none focus:ring-2 focus:ring-blue-500" placeholder="Catatan penerimaan..."></textarea>
              </div>
            </div>

            {/* Daftar barang yang diterima — stok akan otomatis bertambah */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">
                  Daftar Barang Diterima
                </h3>
                <button type="button" onClick={handleAddItemRow} className="flex items-center gap-1.5 text-xs bg-blue-50 hover:bg-blue-100 dark:bg-blue-950/50 dark:hover:bg-blue-900/50 text-blue-600 dark:text-blue-400 font-semibold px-3 py-1.5 rounded-lg transition cursor-pointer">
                  <Plus className="h-3.5 w-3.5" /> Tambah Baris Item
                </button>
              </div>
              <div className="border border-slate-200 dark:border-slate-800 rounded-xl overflow-visible">
                <table className="w-full text-left text-sm">
                  <thead className="bg-slate-100 dark:bg-slate-950 text-slate-500 text-xs uppercase font-semibold">
                    <tr>
                      <th className="px-4 py-3 w-12 text-center">#</th>
                      <th className="px-4 py-3">Part Number / Nama Barang</th>
                      <th className="px-4 py-3 w-36">Jumlah Diterima</th>
                      <th className="px-4 py-3 w-16 text-center">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200 dark:divide-slate-800 bg-white dark:bg-slate-900">
                    {formData.items.map((item, index) => (
                      <tr key={item.id}>
                        <td className="px-4 py-3 text-center text-slate-400 font-medium text-xs">{index + 1}</td>
                        <td className="px-4 py-3">
                          <Select
                            inputId={`ri-item-product-${item.id}`}
                            placeholder="Ketik Part Number / Nama Barang..."
                            isClearable
                            isSearchable
                            options={productOptions}
                            value={productOptions.find(o => o.value === item.productId) || null}
                            onChange={(option) => handleProductSelect(item.id, option)}
                            noOptionsMessage={() => 'Barang tidak ditemukan di inventory'}
                            menuPortalTarget={typeof document !== 'undefined' ? document.body : undefined}
                            styles={{ menuPortal: (base) => ({ ...base, zIndex: 9999 }) }}
                          />
                        </td>
                        <td className="px-4 py-3">
                          <input required type="number" min="1" value={item.quantity} onChange={(e) => handleItemChange(item.id, 'quantity', Number(e.target.value))} className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 dark:text-white" />
                        </td>
                        <td className="px-4 py-3 text-center">
                          <button type="button" onClick={() => handleRemoveItemRow(item.id)} className="p-1.5 hover:bg-rose-50 dark:hover:bg-rose-950/30 text-rose-500 rounded-lg transition cursor-pointer" title="Hapus Baris">
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">
                Jumlah barang yang diterima akan otomatis menambah stok pada menu Inventory.
              </p>
            </div>
            {/* Daftar item yang diterima — stok Inventory bertambah dari sini. */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">Daftar Barang Diterima</h3>
                <button type="button" onClick={handleAddItem} className="flex items-center gap-1.5 text-xs bg-blue-50 hover:bg-blue-100 dark:bg-blue-950/50 text-blue-600 dark:text-blue-400 font-semibold px-3 py-1.5 rounded-lg transition cursor-pointer">
                  <Plus className="h-3.5 w-3.5" /> Tambah Baris
                </button>
              </div>
              <div className="border border-slate-200 dark:border-slate-800 rounded-xl">
                <table className="w-full text-left text-sm">
                  <thead className="bg-slate-100 dark:bg-slate-950 text-slate-500 text-xs uppercase font-semibold">
                    <tr>
                      <th className="px-4 py-3 w-12 text-center">#</th>
                      <th className="px-4 py-3">Part Number / Nama Barang</th>
                      <th className="px-4 py-3 w-28">Kuantitas</th>
                      <th className="px-4 py-3 w-24">Satuan</th>
                      <th className="px-4 py-3 w-16 text-center">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200 dark:divide-slate-800 bg-white dark:bg-slate-900">
                    {formData.items.map((item, index) => (
                      <tr key={index}>
                        <td className="px-4 py-3 text-center text-slate-400 text-xs">{index + 1}</td>
                        <td className="px-4 py-3">
                          <Select
                            options={productOptions}
                            value={productOptions.find((o) => o.value === item.part_number) || null}
                            onChange={(opt) => {
                              handleItemChange(index, 'part_number', opt ? opt.value : '');
                              if (opt) {
                                handleItemChange(index, 'description', opt.name);
                                handleItemChange(index, 'unit', opt.unit);
                              }
                            }}
                            placeholder="Cari & pilih Part Number dari Inventory..."
                            isSearchable
                            isClearable
                            className="text-sm text-slate-800"
                            menuPortalTarget={typeof document !== 'undefined' ? document.body : null}
                            menuPosition="fixed"
                            styles={{
                              menu: (base) => ({ ...base, zIndex: 9999 }),
                              menuPortal: (base) => ({ ...base, zIndex: 9999 }),
                            }}
                          />
                        </td>
                        <td className="px-4 py-3">
                          <input type="number" min="1" value={item.qty} onChange={(e) => handleItemChange(index, 'qty', e.target.value)} className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg text-sm dark:text-white" />
                        </td>
                        <td className="px-4 py-3">
                          <input type="text" value={item.unit} onChange={(e) => handleItemChange(index, 'unit', e.target.value)} className="w-full px-3 py-1.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg text-sm dark:text-white" />
                        </td>
                        <td className="px-4 py-3 text-center">
                          <button type="button" onClick={() => handleRemoveItem(index)} className="p-1.5 hover:bg-rose-50 text-rose-500 rounded-lg transition cursor-pointer" title="Hapus Baris">
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <p className="text-[11px] text-slate-400 mt-2">Stok Inventory akan bertambah otomatis saat data penerimaan disimpan.</p>
            </div>
            <div className="flex justify-end gap-3 pt-4 border-t border-slate-200 dark:border-slate-800">
              <button type="button" onClick={() => setViewMode('list')} className="px-5 py-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg font-medium cursor-pointer">Batal</button>
              <button type="submit" className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg font-medium cursor-pointer"><Save className="h-4 w-4" /> Simpan Data</button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800">
        <div className="p-5 border-b border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row justify-between gap-4">
          <div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" /><input type="text" placeholder="Cari No. RI / Vendor..." className="pl-9 pr-4 py-2 w-full sm:w-72 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg text-sm dark:text-white outline-none focus:ring-2 focus:ring-blue-500" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} /></div>
          <button onClick={handleOpenAddForm} className="flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium cursor-pointer"><Plus className="h-4 w-4" /> Terima Barang</button>
        </div>
        <div className="overflow-x-auto min-h-[300px]">
          {loading ? (
            <div className="text-center py-12 text-slate-400">Memuat data penerimaan...</div>
          ) : (
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                {/* PENAMBAHAN HEADER KOLOM DO DAN SPK DI SINI */}
                <tr>
                  <th className="px-6 py-3">Tanggal</th>
                  <th className="px-6 py-3">No. Penerimaan</th>
                  <th className="px-6 py-3">Vendor</th>
                  <th className="px-6 py-3">Ref. PO</th>
                  <th className="px-6 py-3">Delivery Order</th>
                  <th className="px-6 py-3">No. SPK</th>
                  <th className="px-6 py-3">Status</th>
                  <th className="px-6 py-3 text-center">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-800 dark:text-slate-300">
                {pagination.paginatedItems.length === 0 ? (
                  <tr><td colSpan="8" className="text-center py-8 text-slate-400">Belum ada data penerimaan barang. Silakan proses dari menu PO atau tambah manual.</td></tr>
                ) : (
                  pagination.paginatedItems.map((item, idx) => {
                    const receiveNo = item.receive_no || item.ri_number || item.document_number;
                    const vendor = item.vendor_name || item.supplier_name;
                    const poRef = item.po_ref || item.po_reference || '-';
                    const deliveryOrder = item.delivery_order || '-';
                    const spkSupplier = item.spk_supplier || '-';
                    const keyId = item.id || idx;

                    return (
                      <tr key={keyId} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 relative">
                        <td className="px-6 py-3">{item.date || item.receive_date}</td>
                        <td className="px-6 py-3 font-medium text-blue-600 dark:text-blue-400">{receiveNo}</td>
                        <td className="px-6 py-3">{vendor}</td>
                        <td className="px-6 py-3 text-slate-500">{poRef}</td>
                        
                        {/* PENAMBAHAN DATA BARIS KOLOM DO DAN SPK DI SINI */}
                        <td className="px-6 py-3 text-slate-500">{deliveryOrder}</td>
                        <td className="px-6 py-3 text-slate-500">{spkSupplier}</td>

                        <td className="px-6 py-3">
                            <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${
                                item.status?.includes('Completed') || item.status === 'Diterima Penuh' 
                                ? 'bg-emerald-100 text-emerald-700' 
                                : 'bg-amber-100 text-amber-700'
                            }`}>
                                {item.status || 'Diterima'}
                            </span>
                        </td>
                        <td className="px-6 py-3 text-center">
                          <button onClick={() => setActiveMenuId(activeMenuId === keyId ? null : keyId)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-md cursor-pointer"><MoreVertical className="h-4 w-4" /></button>
                          {activeMenuId === keyId && (
                            <div className="absolute right-12 top-8 w-36 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-lg py-1 z-20 text-left">
                              <button onClick={() => handleEdit(item)} className="w-full px-4 py-2 text-xs flex items-center gap-2 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer"><Edit2 className="h-3.5 w-3.5 text-blue-500" /> Edit</button>
                              
                              <button onClick={() => handlePrint(item)} className="w-full px-4 py-2 text-xs flex items-center gap-2 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer"><Printer className="h-3.5 w-3.5 text-emerald-500" /> Cetak</button>
                              <button onClick={() => handleDelete(keyId)} className="w-full px-4 py-2 text-xs flex items-center gap-2 hover:bg-red-50 dark:hover:bg-red-900/20 text-red-600 cursor-pointer"><Trash2 className="h-3.5 w-3.5" /> Hapus</button>
                            </div>
                          )}
                        </td>
                      </tr>
                    )
                  })
                )}
              </tbody>
            </table>
          )}
        </div>

        {/* Pagination Controller */}
        <Pagination
          currentPage={pagination.currentPage}
          totalItems={pagination.totalItems}
          pageSize={pagination.pageSize}
          onPageChange={pagination.setCurrentPage}
          onPageSizeChange={pagination.setPageSize}
        />
      </div>
    </div>
  );
}
